/**
 * Checks that every id a change points at is usable from the actor's
 * workspace. A reference owned by another workspace is a tenant violation; one
 * that does not exist, is archived, or is otherwise unusable is "not found".
 * Callers run these before writing or announcing anything.
 */
import { isArchived } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Assignees and project leads must be current members of the workspace. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  if ((await memberRepo.findMember(orgId, userId)) === null) {
    throw new NotFoundError("Member", userId);
  }
}

/** Every label must exist and be one of the workspace's own. */
export async function assertLabelsUsable(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const unique = [...new Set(labelIds)];
  const found = new Map(
    (await labelRepo.findLabelsByIdsAnyOrg(unique)).map((label) => [
      label.id,
      label,
    ]),
  );
  for (const id of unique) {
    const label = found.get(id);
    if (label === undefined) throw new NotFoundError("Label", id);
    if (label.orgId !== orgId) throw new TenantScopeError(actor.orgId, label.orgId);
  }
}

/** A parent must be a live issue of the same project. */
export async function assertParentIssueUsable(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueByIdAnyOrg(parentId);
  if (parent === null) throw new NotFoundError("Issue", parentId);
  if (parent.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, parent.orgId);
  }
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

/** A reply target must be a live, top-level comment on the same issue. */
export async function assertReplyTargetUsable(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await commentRepo.findCommentByIdAnyOrg(parentId);
  if (parent === null) throw new NotFoundError("Comment", parentId);
  if (parent.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, parent.orgId);
  }
  if (
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
  return parent;
}
